   "codice": "extends RefCounted\n\nfunc run():\n\tvar body: StaticBody3D = StaticBody3D.new()\n\tbody.collision_mask = 2\n\treturn body.get_collision_mask_value(1)\n",
   "domanda": "Cosa restituisce `get_collision_mask_value(1)`?",
   "spiegazione": "La maschera di collisione è impostata a 2, che attiva solo il secondo layer. Il primo layer non è attivo, quindi `get_collision_mask_value(1)` restituisce `false`."
  }
